+          <div class="footer-row container">
+            <p>© 2026 Northline Goods. Designed for modern retail.</p>
+            <div class="footer-links" aria-label="Footer links">
+              <a href="#">Shipping</a>
+              <a href="#">Returns</a>
+              <a href="#">Contact</a>
+            </div>
+          </div>
+        </footer>
+      `;
+    }
+
+    function App() {
+      return `
+        ${Header()}
+        <main id="main">
+          ${Hero()}
+          ${FeaturedProducts()}
+          ${Deals()}
+          ${Editorial()}
